import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Chickens","description":"","frontmatter":{"title":"Chickens"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Animals/chickens.md","filePath":"Main/Main/GeneralKnowledge/Animals/chickens.md"}'),n={name:"Main/Main/GeneralKnowledge/Animals/chickens.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="chickens" tabindex="-1">Chickens <a class="header-anchor" href="#chickens" aria-label="Permalink to &quot;Chickens&quot;">​</a></h1><p>Chickens are a small livestock animal that produce <strong>Eggs</strong>. They are one of the cheapest production animals and are particularly useful early in the game and for supplying eggs to the <strong>Cake Factory</strong>.</p><h2 id="how-to-obtain" tabindex="-1">How to Obtain <a class="header-anchor" href="#how-to-obtain" aria-label="Permalink to &quot;How to Obtain&quot;">​</a></h2><p>Chickens can be purchased from <strong>AnimalCo</strong>.</p><p>To purchase chickens:</p><ol><li>Take an animal trailer to AnimalCo.</li><li>Position the trailer in the marked animal purchase area.</li><li>Purchase the desired number of chickens.</li><li>The chickens will be loaded into the trailer.</li><li>Transport them back to your farm.</li><li>Place them into a suitable fenced area with access to a Chicken Coop and Small Feeder.</li></ol><p>Chickens are small animals, meaning they can be transported using any suitable animal trailer.</p><h2 id="purchase-price" tabindex="-1">Purchase Price <a class="header-anchor" href="#purchase-price" aria-label="Permalink to &quot;Purchase Price&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>1,500 Coins per Chicken</td></tr><tr><td>Animal Type</td><td>Small Animal</td></tr></tbody></table><p>Each chicken costs <strong>1,500 Coins</strong> when purchased from AnimalCo.</p><h2 id="housing-requirements" tabindex="-1">Housing Requirements <a class="header-anchor" href="#housing-requirements" aria-label="Permalink to &quot;Housing Requirements&quot;">​</a></h2><p>Chickens require a fenced area and a Chicken Coop in order to produce Eggs.</p><p>There are two types of coop available:</p><table tabindex="0"><thead><tr><th>Housing</th><th>Details</th></tr></thead><tbody><tr><td>Chicken Coop</td><td>Standard chicken housing</td></tr><tr><td>Medium Chicken Coop</td><td>Holds twice as many chickens as the regular Chicken Coop</td></tr></tbody></table><p>Chickens must be able to access their coop and feeder.</p><p>The coop also needs to be cleaned regularly to maintain efficient egg production.</p><h2 id="food-requirements" tabindex="-1">Food Requirements <a class="header-anchor" href="#food-requirements" aria-label="Permalink to &quot;Food Requirements&quot;">​</a></h2><p>Chickens eat <strong>Animal Food</strong>.</p><p>They require a <strong>Small Feeder</strong> to provide them with food.</p><p>Animal Food can be purchased from AnimalCo or produced using an <strong>Animal Food Factory</strong>.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td>Food</td><td>Animal Food</td></tr><tr><td>Feeder</td><td>Small Feeder</td></tr><tr><td>Food Source</td><td>AnimalCo / Animal Food Factory</td></tr></tbody></table><blockquote><p><strong>Important:</strong> Keep the feeder stocked with Animal Food so the chickens can continue producing Eggs.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>Chickens produce <strong>Eggs</strong>.</p><p>Eggs are collected from the Chicken Coop once enough eggs have been produced.</p><table tabindex="0"><thead><tr><th>Product</th><th>Details</th></tr></thead><tbody><tr><td>Eggs</td><td>Produced by Chickens</td></tr><tr><td>Egg Box</td><td>Contains 12 Eggs</td></tr></tbody></table><p><strong>12 Eggs</strong> are required to produce one box of Eggs.</p><p>Eggs can be used in the following factories:</p><ul><li>Cake Factory</li><li>Scrambled Egg Factory</li></ul><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed Egg production time is <strong>not currently reliably documented</strong>.</p><p>Eggs are produced relatively quickly, and the coop displays the current egg count so players can check when Eggs are ready to collect.</p><p>Once the coop reaches <strong>12 Eggs</strong>, an Egg Box can be collected.</p><blockquote><p><strong>Note:</strong> A specific production time should be added once confirmed in-game rather than using an unverified value.</p></blockquote><h2 id="selling-information" tabindex="-1">Selling Information <a class="header-anchor" href="#selling-information" aria-label="Permalink to &quot;Selling Information&quot;">​</a></h2><p>Eggs can be sold at <strong>AnimalCo</strong>.</p><p>Egg Boxes can be transported using a trailer, truck, or carried by hand.</p><table tabindex="0"><thead><tr><th>Product</th><th>Selling Information</th></tr></thead><tbody><tr><td>Eggs</td><td>Sold at AnimalCo</td></tr><tr><td>Egg Box</td><td>Contains 12 Eggs</td></tr></tbody></table><p>Eggs can also be used as an ingredient rather than sold directly.</p><p>Using Eggs in the <strong>Cake Factory</strong> can make them useful as part of a larger production chain.</p><h2 id="required-license" tabindex="-1">Required License <a class="header-anchor" href="#required-license" aria-label="Permalink to &quot;Required License&quot;">​</a></h2><table tabindex="0"><thead><tr><th>License</th><th>Required</th></tr></thead><tbody><tr><td>Chicken License</td><td>No</td></tr></tbody></table><p>Chickens do <strong>not</strong> require a specific license to purchase.</p><p>They are introduced early through the <strong>Animals Goals</strong> progression.</p><h2 id="other-useful-information" tabindex="-1">Other Useful Information <a class="header-anchor" href="#other-useful-information" aria-label="Permalink to &quot;Other Useful Information&quot;">​</a></h2><ul><li>Chickens cost <strong>1,500 Coins</strong> each.</li><li>Chickens are classified as <strong>small animals</strong>.</li><li>Chickens require a <strong>Chicken Coop</strong> or <strong>Medium Chicken Coop</strong> to produce Eggs.</li><li>The Medium Chicken Coop holds <strong>twice as many chickens</strong> as the standard Chicken Coop.</li><li>Chickens use a <strong>Small Feeder</strong>.</li><li>Chickens eat <strong>Animal Food</strong>.</li><li>Coops need to be cleaned regularly.</li><li>One Egg Box contains <strong>12 Eggs</strong>.</li><li>Eggs can be used in the <strong>Cake Factory</strong>.</li><li>Eggs can also be used in the <strong>Scrambled Egg Factory</strong>.</li><li>Chickens are one of the cheapest production animals but have relatively low income compared with cows and other advanced production animals.</li><li>Chickens are useful for completing early <strong>Animals Goals</strong>, including collecting and selling Eggs.</li><li>Chickens can be purchased from <strong>AnimalCo</strong> and transported to your farm using an animal trailer.</li></ul>',46)])])}const p=t(n,[["render",i]]);export{u as __pageData,p as default};
